import { NextResponse } from "next/server";
import { z } from "zod";
import { findBookmarkByUrlKey } from "@/lib/bookmarks/repository";
import { AppError, errorResponse } from "@/lib/errors";
import { createMetadataPreview } from "@/lib/metadata/service";
import { assertSameOrigin } from "@/lib/security/origin";
import { normalizeUrl } from "@/lib/urls/normalize";

export const runtime = "nodejs";
const requestSchema = z.object({ url: z.string().trim().min(1).max(2048) }).strict();

const windows = new Map<string, { count: number; reset: number }>();
function rateLimit(request: Request) {
  const now = Date.now();
  const key = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "local";
  const current = windows.get(key);
  if (!current || current.reset <= now) { windows.set(key, { count: 1, reset: now + 60_000 }); return; }
  if (current.count >= 20) throw new AppError("RATE_LIMITED", "Too many previews. Please wait a moment.", 429);
  current.count += 1;
}

export async function POST(request: Request) {
  try {
    assertSameOrigin(request);
    rateLimit(request);
    const parsed = requestSchema.safeParse(await request.json());
    if (!parsed.success) throw new AppError("VALIDATION_ERROR", parsed.error.issues[0]?.message ?? "Invalid URL.", 422, "url");
    const preview = await createMetadataPreview(parsed.data.url, {
      normalizeUrl,
      findExistingId: async (url) => (await findBookmarkByUrlKey(normalizeUrl(url).key))?.id ?? null
    });
    return NextResponse.json(preview);
  } catch (error) { return errorResponse(error); }
}
import { AppError } from "../errors";
import { bookmarkListQuerySchema, bookmarkWriteSchema } from "./schemas";
import * as repository from "./repository";

function parseOrValidationError<T>(result: { success: true; data: T } | { success: false; error: { issues: Array<{ path: PropertyKey[]; message: string }> } }): T {
  if (result.success) return result.data;
  const issue = result.error.issues[0];
  throw new AppError("VALIDATION_ERROR", issue?.message ?? "Invalid input.", 422, issue?.path[0]?.toString());
}

export async function createBookmark(input: unknown) {
  return repository.createBookmark(parseOrValidationError(bookmarkWriteSchema.safeParse(input)));
}
export async function updateBookmark(id: string, input: unknown) {
  return repository.updateBookmark(id, parseOrValidationError(bookmarkWriteSchema.safeParse(input)));
}
export async function getBookmark(id: string) { return repository.getBookmark(id); }
export async function deleteBookmark(id: string) { return repository.deleteBookmark(id); }
export async function listBookmarks(input: unknown) {
  return repository.listBookmarks(parseOrValidationError(bookmarkListQuerySchema.safeParse(input)));
}
import { NextResponse } from "next/server";

export type ErrorCode = "VALIDATION_ERROR" | "NOT_FOUND" | "DUPLICATE_URL" | "RATE_LIMITED" | "INTERNAL_ERROR";

export class AppError extends Error {
  constructor(
    public readonly code: ErrorCode,
    message: string,
    public readonly status: number,
    public readonly field?: string,
    public readonly existingId?: string
  ) { super(message); this.name = "AppError"; }
}

export function errorResponse(error: unknown): NextResponse {
  const known = error instanceof AppError ? error : new AppError("INTERNAL_ERROR", "That action could not be completed.", 500);
  return NextResponse.json({ error: {
    code: known.code,
    message: known.message,
    ...(known.field ? { field: known.field } : {}),
    ...(known.existingId ? { existingId: known.existingId } : {})
  } }, { status: known.status });
}

